function renderResolution(block){const p=block.presentation||{},sequence=Number(p.event_sequence||1),eventKey=`${block.resolution_id}:${sequence}`,seen=state.animatedResolutions.has(eventKey),row=text("section","",`resolution-reference resolution-${p.status||"unknown"}`),statusNames={pending:"等待选择",choice:"等待选择",settled:"已结算",aborted:"已中止",failed:"失败"},status=statusNames[p.status]||"权威判定",rolls=Array.isArray(p.rolls)?p.rolls:[],outcome=p.outcome||{},summary=[];row.dataset.resolutionId=block.resolution_id;row.dataset.eventSequence=String(sequence);row.setAttribute("role","status");if(!seen&&!state.hydratingRoom)row.classList.add("resolution-enter");state.animatedResolutions.add(eventKey);row.append(text("span",p.system_id==="coc7e"?"◉":"⚄","resolution-die"),text("strong",status));for(const roll of rolls){const dice=Array.isArray(roll.dice)?roll.dice.join(", "):"—",line=text("div","","resolution-roll");line.append(text("span",`${roll.expression||"骰点"} [${dice}]`),text("strong",`＝ ${roll.total}`));row.append(line);summary.push(`${roll.expression||"骰点"}，骰值 ${dice}，合计 ${roll.total}`)}const outcomeParts=[];for(const key of ["success_level","outcome","success","hit","critical","fumble","damage","san_loss"]){if(outcome[key]!==undefined&&outcome[key]!==null)outcomeParts.push(`${key}: ${String(outcome[key])}`)}if(outcomeParts.length)row.append(text("small",outcomeParts.join(" · "),"resolution-outcome"));const pending=p.pending_choice,actions=Array.isArray(pending?.available_actions)?pending.available_actions:[];if(actions.length){const choices=text("div","","resolution-choices");choices.setAttribute("aria-label","可选择的后续结算");for(const action of actions)choices.append(button(action,()=>insertSuggestion(action),"resolution-choice"));row.append(choices)}row.setAttribute("aria-label",`${status}。${summary.join("；")}。${outcomeParts.join("；")}`);return row}
function renderPresentation(payload,fallback){const body=text("div","","message-body presentation-body"),blocks=Array.isArray(payload?.blocks)?payload.blocks:[];if(!blocks.length){body.append(text("div",fallback||""));return body}for(const block of blocks){if(block.type==="narration")body.append(text("p",block.text||"","narration-block"));else if(block.type==="performance")body.append(renderPerformance(block));else if(block.type==="resolution_ref")body.append(renderResolution(block));else if(block.type==="prompt")body.append(text("p",block.text||"","turn-prompt"))}return body}
