function connectRoomEvents(){if(state.roomEvents)state.roomEvents.close();const campaignId=state.campaign.id,source=new EventSource(`/api/campaigns/${campaignId}/room/events?after=${state.roomEventCursor}`),activityNames={reviewing_rules:"正在查阅规则",checking_range:"正在确认距离",resolving_roll:"正在结算骰点",settling_save:"正在结算豁免",awaiting_choice:"等待选择",updating_state:"正在更新状态",preparing_narration:"正在准备叙述"};state.roomEvents=source;source.onopen=()=>{$("#room-sync").textContent="实时同步";$("#room-sync").classList.add("online")};source.onerror=()=>{$("#room-sync").textContent="正在重连";$("#room-sync").classList.remove("online")};const receive=e=>{if(state.campaign?.id!==campaignId)return;state.roomEventCursor=Math.max(state.roomEventCursor,Number(e.lastEventId||0));const value=JSON.parse(e.data||"{}");if(value.message)updateMessage(value.message);return value};source.addEventListener("message.created",receive);source.addEventListener("message.updated",receive);source.addEventListener("agent.started",e=>{$("#room-sync").textContent="Agent 正在处理";receive(e)});source.addEventListener("room.activity",e=>{const value=receive(e)||{};$("#room-sync").textContent=value.state==="started"?(activityNames[value.code]||"Agent 正在处理"):"Agent 正在处理"});source.addEventListener("agent.completed",e=>{receive(e);refreshPanel();loadUsage()});source.addEventListener("agent.failed",receive);source.addEventListener("state.changed",e=>{receive(e);refreshPanel().then(refreshSuggestionValidity)});source.addEventListener("host.changed",e=>{receive(e);const value=JSON.parse(e.data||"{}");if(state.room)state.room.host_identity_assignment_id=value.identity_assignment_id||null;identityController.loadCampaignIdentities()});source.addEventListener("access.revoked",()=>{source.close();toast("你的战役访问已被撤销");$("#back-campaigns").click()})}
